15: 	findings := []store.ReviewFindingDetail{{PatternSeq: 2, Severity: "P3", State: "open", Origin: "introduced", InScope: true}}
16: 	if selectedReviewPatternsBlock(findings, map[int]bool{2: true}, plan) {
17: 		t.Fatal("non-blocking pattern qualified as a blocking-finding repair")
18: 	}
19: 	findings = append(findings, store.ReviewFindingDetail{PatternSeq: 3, Severity: "P1", State: "open", Origin: "introduced", InScope: true})
20: 	if !selectedReviewPatternsBlock(findings, map[int]bool{2: true, 3: true}, plan) {
21: 		t.Fatal("selected blocking pattern did not qualify the repair round")
22: 	}
23: }
