25: func TestFullPipelineReviewCapCountsOnlyBlockingFindingRepairs(t *testing.T) {
26: 	fixture := newPRMergeFixture(t, "pr", store.StateDone)
27: 	installValidationPlanForReview(t, fixture, "full-pipeline")
28: 	task, err := fixture.db.TaskByID(context.Background(), fixture.project.ID, fixture.task.ID)
29: 	if err != nil {
30: 		t.Fatal(err)
31: 	}
32: 	outcomes := []string{"findings", "clean", "clean", "findings"}
33: 	for i, outcome := range outcomes {
34: 		head := strings.Repeat("0", 39) + string(rune('1'+i))
35: 		verdict := store.Verdict{TaskID: task.ID, Repository: "shop", Provider: store.GreenhouseReviewProvider, Protocol: "2",
36: 			Grant: "shop/t1/review-" + string(rune('1'+i)), Head: head, Target: head, ReviewBase: head,
37: 			Outcome: outcome, Mode: "gate"}
38: 		if outcome == "findings" {
39: 			verdict.Blocking = 1
40: 		}
41: 		if recorded, err := fixture.db.RecordGreenhouseVerdict(context.Background(), verdict, func(context.Context) (string, error) { return head, nil }); err != nil || !recorded {
42: 			t.Fatalf("record review %d (%s): recorded=%v err=%v", i+1, outcome, recorded, err)
43: 		}
44: 	}
45: 	if _, err := fixture.db.QueueValidationFixInstruction(context.Background(), task.ID, "review", strings.Repeat("0", 39)+"1", "review:first-findings", "Fix blocking findings"); err != nil {
46: 		t.Fatal(err)
47: 	}
48: 	usage, err := fixture.db.ReviewCapUsage(context.Background(), task.ID)
49: 	if err != nil {
50: 		t.Fatal(err)
51: 	}
52: 	if usage.Total() != 5 {
53: 		t.Fatalf("historical Review/repair total = %d, want the reported 5 of 3 sequence", usage.Total())
54: 	}
55: 	if got := reviewCapUsed(task, usage); got != 1 {
56: 		t.Fatalf("Review cap used = %d, want 1 blocking-finding repair despite four Verdicts", got)
57: 	}
58: 	if got := reviewCapUsageDescription(task, reviewCapUsed(task, usage), 3); strings.Contains(got, "5 of 3") || !strings.Contains(got, "target-merge re-reviews") {
59: 		t.Fatalf("Review cap Notice description = %q", got)
60: 	}
61: 	if got := reviewCapUsageDescription(task, 5, 3); !strings.Contains(got, "excess is from prior or User-authorized fixes") {
62: 		t.Fatalf("over-cap Notice description does not explain the excess: %q", got)
63: 	}
64: 	if got := reviewCapRule(task, 3); !strings.Contains(got, "re-reviews") || !strings.Contains(got, "blocking findings") {
65: 		t.Fatalf("Review cap rule = %q, want it to explain counted repairs and excluded re-reviews", got)
66: 	}
67: }
