package store

import (
	"context"
	"errors"
	"fmt"
	"time"
)

var (
	ErrReviewRoundActive         = errors.New("review round is already active")
	ErrReviewRoundUnchanged      = errors.New("change head is unchanged since its last review")
	ErrReviewRoundCap            = errors.New("review round cap reached")
	ErrReviewRoundNumber         = errors.New("review round number changed concurrently")
	ErrReviewResolutionsRequired = errors.New("review fix resolutions are required")
	ErrReviewResolutionsInvalid  = errors.New("review fix resolutions are invalid")
)

// ReviewRoundAdmission binds a new Review Task to one numbered round. All
// repository bindings are inserted with the Task in the same transaction.
type ReviewRoundAdmission struct {
	ChangeTaskID       int64
	Round              int
	MaxRounds          int
	SharedRepairBudget bool
	Bindings           []ReviewRound
}

type ReviewLedgerEntry struct {
	FindingSeq  int
	PatternSeq  int
	PatternKey  string
	State       string
	Severity    string
	Fingerprint string
}

// ReviewLedgerFor returns the Change Task's current finding ledger in stable ID order.
func (db *DB) ReviewLedgerFor(ctx context.Context, changeTaskID int64) ([]ReviewLedgerEntry, error) {
	rows, err := db.QueryContext(ctx, `SELECT f.seq,COALESCE(parent.seq,p.seq),COALESCE(parent.key,p.key),CASE WHEN f.inherited_from IS NOT NULL THEN 'inherited' ELSE f.state END,f.severity,f.fingerprint FROM review_findings f JOIN review_patterns p ON p.id=f.pattern_id LEFT JOIN review_patterns parent ON parent.id=p.merged_into WHERE f.ship_task_id=? ORDER BY f.seq`, changeTaskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var entries []ReviewLedgerEntry
	for rows.Next() {
		var entry ReviewLedgerEntry
		if err := rows.Scan(&entry.FindingSeq, &entry.PatternSeq, &entry.PatternKey, &entry.State, &entry.Severity, &entry.Fingerprint); err != nil {
			return nil, err
		}
		entries = append(entries, entry)
	}
	return entries, rows.Err()
}

func (db *DB) VoidUnverdictReviewRound(ctx context.Context, reviewTaskID int64) error {
	_, err := db.ExecContext(ctx, `UPDATE review_rounds SET status='void'
WHERE review_task_id=? AND status='admitted'
  AND NOT EXISTS (SELECT 1 FROM review_verdicts v WHERE v.task_id=review_rounds.review_task_id)`, reviewTaskID)
	return err
}

// ReviewRoundsFor returns the immutable bindings and current status for every
// round of a Change Task.
func (db *DB) ReviewRoundsFor(ctx context.Context, changeTaskID int64) ([]ReviewRound, error) {
	rows, err := db.QueryContext(ctx, `SELECT ship_task_id,round,review_task_id,repository,scope_kind,scope_base_sha,head_sha,target_commit_sha,baseline_tree,delta_sha256,conflicted_paths_json,status,COALESCE(verdict,''),created_at FROM review_rounds WHERE ship_task_id=? ORDER BY round,repository,review_task_id`, changeTaskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var rounds []ReviewRound
	for rows.Next() {
		var round ReviewRound
		if err := rows.Scan(&round.ChangeTaskID, &round.Round, &round.ReviewTaskID, &round.Repository, &round.ScopeKind, &round.ScopeBaseSHA, &round.HeadSHA, &round.TargetCommitSHA, &round.BaselineTree, &round.DeltaSHA256, &round.ConflictedPaths, &round.Status, &round.Verdict, &round.CreatedAt); err != nil {
			return nil, err
		}
		rounds = append(rounds, round)
	}
	return rounds, rows.Err()
}

// ReviewTargetsCovered reports whether every target has a verdict, a proved
// carry, or an exact-head User disposition, so no further Review Round is due.
func (db *DB) ReviewTargetsCovered(ctx context.Context, changeTaskID int64, targets []ReviewTarget) (bool, error) {
	for _, target := range targets {
		var covered bool
		if err := db.QueryRowContext(ctx, `SELECT EXISTS(
SELECT 1 FROM review_rounds WHERE ship_task_id=? AND repository=? AND status='verdict' AND head_sha=?
UNION ALL
SELECT 1 FROM review_carries WHERE ship_task_id=? AND repository=? AND to_head=?
UNION ALL
SELECT 1 FROM review_dispositions WHERE ship_task_id=? AND head_sha=?)`,
			changeTaskID, target.Repository, target.Commit,
			changeTaskID, target.Repository, target.Commit,
			changeTaskID, target.Commit).Scan(&covered); err != nil || !covered {
			return false, err
		}
	}
	return len(targets) > 0, nil
}

func validateReviewRoundAdmissionTx(ctx context.Context, tx *writeTx, admission ReviewRoundAdmission) error {
	if admission.ChangeTaskID < 1 || admission.Round < 1 || admission.MaxRounds < 1 || admission.MaxRounds > 3 || len(admission.Bindings) == 0 {
		return fmt.Errorf("invalid review round admission")
	}
	var taskType string
	if err := tx.QueryRowContext(ctx, `SELECT type FROM tasks WHERE id=?`, admission.ChangeTaskID).Scan(&taskType); err != nil {
		return err
	}
	if taskType != "change" {
		return fmt.Errorf("review round target is not a Change Task")
	}
	// A completed Review Task without a recorded verdict is a void round. Settle
	// it here as well as on admission so crashes and older transitions cannot
	// leave the active-round guard stuck indefinitely.
	if _, err := tx.ExecContext(ctx, `UPDATE review_rounds SET status='void'
WHERE ship_task_id=? AND status='admitted'
  AND EXISTS (SELECT 1 FROM tasks r WHERE r.id=review_rounds.review_task_id AND r.state IN ('failed','lost','reported','torn-down'))
  AND NOT EXISTS (SELECT 1 FROM review_verdicts v WHERE v.task_id=review_rounds.review_task_id)`, admission.ChangeTaskID); err != nil {
		return err
	}
	var active bool
	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(
SELECT 1 FROM review_rounds rr JOIN tasks r ON r.id=rr.review_task_id
WHERE rr.ship_task_id=? AND rr.status='admitted'
  AND r.state NOT IN ('failed','lost','reported','torn-down'))`, admission.ChangeTaskID).Scan(&active); err != nil {
		return err
	}
	if active {
		return ErrReviewRoundActive
	}
	var used int
	if err := tx.QueryRowContext(ctx, `SELECT COUNT(DISTINCT round) FROM review_rounds WHERE ship_task_id=? AND status='verdict'`, admission.ChangeTaskID).Scan(&used); err != nil {
		return err
	}
	if admission.Round != used+1 {
		return ErrReviewRoundNumber
	}
	seen := make(map[string]bool, len(admission.Bindings))
	anyNewHead := false
	for _, binding := range admission.Bindings {
		if binding.ChangeTaskID != admission.ChangeTaskID || binding.Round != admission.Round || binding.Repository == "" || seen[binding.Repository] || binding.Status != "admitted" || binding.Verdict != "" {
			return fmt.Errorf("invalid repository binding in review round admission")
		}
		seen[binding.Repository] = true
		var unchanged bool
		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(
SELECT 1 FROM review_rounds WHERE ship_task_id=? AND repository=? AND status='verdict' AND head_sha=?
UNION ALL
SELECT 1 FROM review_carries WHERE ship_task_id=? AND repository=? AND to_head=?)`,
			admission.ChangeTaskID, binding.Repository, binding.HeadSHA,
			admission.ChangeTaskID, binding.Repository, binding.HeadSHA).Scan(&unchanged); err != nil {
			return err
		}
		if !unchanged {
			anyNewHead = true
		}
	}
	var finalReview bool
	if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM review_cap_grants WHERE task_id=? AND round=?)`, admission.ChangeTaskID, admission.Round).Scan(&finalReview); err != nil {
		return err
	}
	if finalReview {
		var pending bool
		if err := tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM validation_fix_rounds r JOIN messages m ON m.id=r.message_id WHERE r.ship_task_id=? AND r.kind='review' AND m.status IN ('queued','claimed','interrupting','submitting','delivered') AND m.created_at>COALESCE((SELECT MAX(at) FROM signals WHERE task_id=? AND verb='done'),0))`, admission.ChangeTaskID, admission.ChangeTaskID).Scan(&pending); err != nil {
			return err
		}
		if pending {
			return ErrReviewRoundActive
		}
	}
	if !anyNewHead && !finalReview {
		return ErrReviewRoundUnchanged
	}
	if !admission.SharedRepairBudget && used >= admission.MaxRounds && !finalReview {
		return ErrReviewRoundCap
	}
	return nil
}

func insertReviewRoundBindingsTx(ctx context.Context, tx *writeTx, reviewTaskID int64, admission ReviewRoundAdmission) error {
	createdAt := time.Now().UnixMilli()
	for _, binding := range admission.Bindings {
		if _, err := tx.ExecContext(ctx, `INSERT INTO review_rounds(ship_task_id,round,review_task_id,repository,scope_kind,scope_base_sha,head_sha,target_commit_sha,baseline_tree,delta_sha256,conflicted_paths_json,status,verdict,created_at)
VALUES(?,?,?,?,?,?,?,?,?,?,?,'admitted',NULL,?)`,
			admission.ChangeTaskID, admission.Round, reviewTaskID, binding.Repository, binding.ScopeKind, binding.ScopeBaseSHA, binding.HeadSHA, binding.TargetCommitSHA, binding.BaselineTree, binding.DeltaSHA256, binding.ConflictedPaths, createdAt); err != nil {
			return err
		}
	}
	return nil
}

	var pending bool
	err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM validation_fix_rounds r JOIN messages m ON m.id=r.message_id
WHERE r.ship_task_id=? AND r.kind='review' AND m.status IN ('queued','claimed','interrupting','submitting','delivered')
AND m.created_at>COALESCE((SELECT MAX(at) FROM signals WHERE task_id=? AND verb='done'),0))`, taskID, taskID).Scan(&pending)
	return pending, err
}

// ReviewCapUsage combines verdict-recorded rounds with Review fix
// instructions. CI fix rounds and provider cancellation reruns never count.
func (db *DB) ReviewCapUsage(ctx context.Context, taskID int64) (ReviewCapUsage, error) {
	var usage ReviewCapUsage
	if err := db.QueryRowContext(ctx, `SELECT
(SELECT COUNT(DISTINCT round) FROM review_rounds WHERE ship_task_id=? AND status='verdict') +
(SELECT COUNT(*) FROM verdicts WHERE task_id=? AND provider='greenhouse' AND mode='gate')`, taskID, taskID).Scan(&usage.ReviewRounds); err != nil {
		return usage, err
	}
	if err := db.QueryRowContext(ctx, `SELECT COUNT(*) FROM validation_fix_rounds WHERE ship_task_id=? AND kind='review'`, taskID).Scan(&usage.RepairRounds); err != nil {
		return usage, err
	}
	return usage, nil
}

// ReviewEvidenceFor reports whether the targets are covered by one pass, with
// any target outside that pass covered by a proved carry or an exact-head User
// disposition. Passes from different Review Rounds are never
// combined: a workspace pass binds the Member heads its Reviewer saw together,
// so it covers exactly those heads, or a subset of them. Carries and
// dispositions never imply test, docs, lint or CI evidence.
func (db *DB) ReviewEvidenceFor(ctx context.Context, taskID int64, targets []ReviewTarget) (ReviewEvidence, error) {
	var evidence ReviewEvidence
	if len(targets) == 0 {
		return evidence, nil
	}
	verdicts, err := db.ReviewVerdictsFor(ctx, taskID)
	if err != nil {
		return evidence, err
	}
	carried := make([]bool, len(targets))
	disposed := make([]bool, len(targets))
	for index, target := range targets {
		if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM review_carries WHERE ship_task_id=? AND repository=? AND to_head=?)`, taskID, target.Repository, target.Commit).Scan(&carried[index]); err != nil {
			return evidence, err
		}
		if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM review_dispositions WHERE ship_task_id=? AND head_sha=?)`, taskID, target.Commit).Scan(&disposed[index]); err != nil {
			return evidence, err
		}
	}
	// coveredBy reports whether reviewed, plus carries and dispositions, covers
	// every target, and records which evidence it needed.
	coveredBy := func(reviewed []ReviewTarget) (ReviewEvidence, bool) {
		result := ReviewEvidence{Complete: true}
		for index, target := range targets {
			if slices.Contains(reviewed, target) {
				result.Pass = true
				continue
			}
			if !carried[index] && !disposed[index] {
				return ReviewEvidence{}, false
			}
			result.Carry = result.Carry || carried[index]
			result.Disposition = result.Disposition || disposed[index]
		}
		return result, true
	}
	for _, verdict := range verdicts {
		if verdict.Verdict != ReviewPass {
			continue
		}
		if result, ok := coveredBy(verdict.Targets); ok && result.Pass {
			return result, nil
		}
	}
	if result, ok := coveredBy(nil); ok {
		return result, nil
	}
	for index := range targets {
		evidence.Carry = evidence.Carry || carried[index]
		evidence.Disposition = evidence.Disposition || disposed[index]
	}
	return evidence, nil
}

// RecordReviewCarry persists proof that a target merge changes no reviewed code.
func (db *DB) RecordReviewCarry(ctx context.Context, carry ReviewCarry) error {
	if carry.ChangeTaskID < 1 || carry.Repository == "" || !validValidationSHA(carry.FromHead) || !validValidationSHA(carry.ToHead) || !validValidationSHA(carry.TargetCommitSHA) || !validValidationSHA(carry.Tree) {
		return fmt.Errorf("invalid Review carry")
	}
	if carry.CreatedAt == 0 {
		carry.CreatedAt = time.Now().UnixMilli()
	}
	_, err := db.ExecContext(ctx, `INSERT INTO review_carries(ship_task_id,repository,from_head,to_head,target_commit_sha,tree,created_at)
VALUES(?,?,?,?,?,?,?) ON CONFLICT(ship_task_id,repository,from_head,to_head) DO NOTHING`,
		carry.ChangeTaskID, carry.Repository, carry.FromHead, carry.ToHead, carry.TargetCommitSHA, carry.Tree, carry.CreatedAt)
	if err != nil {
		return err
	}
	return db.PersistTask(ctx, carry.ChangeTaskID)
}

