18: // The tests in this file prove the built-in validation loop against a frozen
19: // `staging` target. Origin staging is one commit ahead of main, so a candidate
20: // bound to the default branch instead of the Task's target is detectable, and
21: // every step audits the full ref set of each bare origin.
22: 
23: // stagingTarget creates origin staging one commit ahead of main and makes the
24: // fake forge report staging as every PR base. It returns the staging head.
25: func stagingTarget(t *testing.T, f *prLifecycleFixture) string {
26: 	t.Helper()
27: 	main := gitRef(t, f, f.remote, "refs/heads/main")
28: 	staging := advanceBranch(t, f, f.remote, "staging", main, "staging-only commit")
29: 	if err := os.WriteFile(filepath.Join(f.root, "gh-base-branch"), []byte("staging\n"), 0o600); err != nil {
30: 		t.Fatal(err)
31: 	}
32: 	return staging
33: }
34: 
35: // advanceBranch commits on top of parent directly in gitDir and points branch
36: // at the commit, as an outside push to a bare origin would. An empty parent
37: // uses the current branch head.
